example.programlisting:
using System;
using System.IO;
using Rexx.Net;

using var rexx = RexxInterpreter.Create();
Console.WriteLine(rexx.Run<int>("use arg a, b; return a + b", 2, 3));
string path = Path.Combine(Path.GetTempPath(), "book-join.rex");
File.WriteAllText(path, "use arg a, b\nreturn a b\n");
Console.WriteLine(rexx.RunFile(path, "x", "y"));
var pkg = rexx.LoadPackage("counter.cls",
    "::class Counter public\n" +
    "::attribute n get\n" +
    "::method init; expose n; n = 0\n" +
    "::method add; expose n; use arg k = 1; n += k; return self\n");
RexxClass counter = pkg.FindClass("Counter")!;
RexxObject c = counter.New()!;
c.Send("add", 5)!.Send("add");                 // Rexx's c~add(5)~add
Console.WriteLine(c.Send<int>("n"));
dynamic d = c;                                // or through dynamic
d.add(10);
Console.WriteLine((int)d.n);
Console.WriteLine($"{counter.Name} {c.Is(counter)} {c.HasMethod("ADD")}");

section.programlisting:
public sealed class RexxInterpreter : IDisposable
{
    public static RexxInterpreter Create(RexxOptions? options = null);
    public static RexxInterpreter? Current { get; }
    public bool IsGuest { get; }
    public string Version { get; }
    public string LanguageLevel { get; }

    public RexxObject? Run(string source, params object?[] args);
    public T Run<T>(string source, params object?[] args);
    public RexxObject? RunFile(string path, params object?[] args);
    public RexxRoutine Compile(string name, string source);
    public RexxPackage LoadPackage(string path);
    public RexxPackage LoadPackage(string name, string source);
    public RexxClass? FindClass(string name);
    public RexxObject Environment { get; }
    public RexxObject Local { get; }
    public RexxObject NewArray(params object?[] items);
    public RexxObject NewDirectory(IEnumerable<KeyValuePair<string, object?>> pairs);
    public RexxObject NewStringTable(IEnumerable<KeyValuePair<string, object?>> pairs);
    public RexxScope Enter();
    public void RequireNet();
    public int ObjectCount { get; }
    public void Dispose();
    // and those of the next chapter: commands, streams, functions, cancellation
}

public sealed class RexxOptions
{
    public string? InitialAddress { get; set; }
    public string? ExternalCallPath { get; set; }
    public string? ExternalCallExtensions { get; set; }
    public IList<string> LoadLibraries { get; }
    public bool ReliableCancellation { get; set; } = true;
    public TextWriter? Output { get; set; }
    public TextWriter? Error { get; set; }
    public TextReader? Input { get; set; }
    public bool Net { get; set; } = true;
    public bool StreamPrefixes { get; set; } = true;
}

public class RexxObject : DynamicObject, IEnumerable<object?>, IDisposable
{
    public RexxInterpreter Interpreter { get; }
    public object? NetValue { get; }
    public RexxObject? Send(string name, params object?[] args);
    public T Send<T>(string name, params object?[] args);
    public RexxObject? Send(string name, CancellationToken cancel, params object?[] args);
    public T Send<T>(string name, CancellationToken cancel, params object?[] args);
    public RexxObject? SendMessage(string name, params object?[]? args);
    public RexxObject? SendMessage0(string name);   // ... SendMessage5(name, a1, ..., a5)
    public RexxObject? SendMessageScope(string name, RexxClass scope, params object?[]? args);
    public object? this[params object?[] index] { get; set; }
    public bool Is(RexxClass cls);
    public bool HasMethod(string name);
    public IReadOnlyList<KeyValuePair<object?, object?>> Supplier();
    public IEnumerator<object?> GetEnumerator();
    public override string ToString();
    public void Dispose();
}

listitem.para:
For a Rexx NetObject, its .NET object
(for a NetType, its System.Type);
null for any other Rexx object.

section.programlisting:
public sealed class RexxString : RexxObject, IEquatable<RexxString>, IConvertible
{
    public RexxString(string value);
    public string Value { get; }
    public static explicit operator string(RexxString s);   // and int, long, double...
}

public sealed class RexxClass : RexxObject
{
    public RexxObject? New(params object?[] args);       // ~new(args)
    public string Name { get; }                          // ~id
    public RexxClass? SuperClass { get; }                // null for Object
}
public sealed class RexxRoutine : RexxObject
{
    public RexxObject? Call(params object?[] args);
    public T Call<T>(params object?[] args);
    public RexxObject? Call(CancellationToken cancel, params object?[] args);
    public T Call<T>(CancellationToken cancel, params object?[] args);
}
public sealed class RexxPackage : RexxObject
{
    public string Name { get; }
    public RexxClass? FindClass(string name);           // its own, or one it can see
    public IReadOnlyDictionary<string, RexxObject?> Classes { get; }
    public IReadOnlyDictionary<string, RexxObject?> PublicClasses { get; }
    public IReadOnlyDictionary<string, RexxObject?> Routines { get; }
    public IReadOnlyDictionary<string, RexxObject?> PublicRoutines { get; }
}

public static class RexxConvert
{
    public static T To<T>(object? v);
    public static object? To(object? v, Type t);
    public static bool ToBool(string s);
}
public static class RexxValue
{
    public static readonly object Omitted;
}
public sealed class RexxScope : IDisposable { public void Dispose(); }

example.programlisting:
using System;
using System.Collections.Generic;
using System.Text;
using Rexx.Net;

using var rexx = RexxInterpreter.Create();
dynamic s = rexx.Run("return '150'")!;
Console.WriteLine(s + 1);                      // Rexx's +
int n = s;
Console.WriteLine(n * 2);
int[] ints = rexx.Run<int[]>("return .array~of(1, 2, 3)");
Console.WriteLine(string.Join(",", ints));
var dict = rexx.Run<Dictionary<string, int>>("t = .stringTable~new; t['a'] = 1; t['b'] = 2; return t");
Console.WriteLine($"{dict["b"]} {dict.Count}");
var arr = rexx.NewArray(1, "two", 3.5);
Console.WriteLine($"{arr.Send<int>("items")} {arr[2]}");
var sb = new StringBuilder("ab");
rexx.Run("use arg sb; sb~Append('cd')", sb);  // a NetObject in Rexx
Console.WriteLine(sb);
Console.WriteLine(ReferenceEquals(rexx.Run<StringBuilder>("use arg o; return o", sb), sb));

section.programlisting:
public sealed class RexxException : Exception
{
    public string ConditionName { get; }    // "SYNTAX", "HALT", ...
    public string Code { get; }             // "41.1" (empty but for SYNTAX)
    public int Rc { get; }                  // 41
    public string ErrorText { get; }        // "Bad arithmetic conversion."
    public string Program { get; }
    public int Line { get; }
    public string Traceback { get; }        // as Rexx shows it
    public RexxObject? Condition { get; }   // condition("O"), for a call made from .NET
}

example.programlisting:
using System;
using Rexx.Net;

using var rexx = RexxInterpreter.Create();
try { rexx.Run("x = 1\nreturn x + 'a'"); }
catch (RexxException e) { Console.WriteLine($"{e.ConditionName} {e.Code} line {e.Line}: {e.Message}"); }
try { rexx.Run("return .net~System~Int32~Parse('x')"); }
catch (RexxException e) { Console.WriteLine($"{e.Code} {e.InnerException?.GetType().Name}"); }
try { rexx.Compile("bad", "x = (1"); }
catch (RexxException e) { Console.WriteLine($"{e.Code} {e.ErrorText}"); }
